const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { DynamoDBDocumentClient, GetCommand } = require('@aws-sdk/lib-dynamodb');
const { buildSubgraphSchema } = require('@apollo/subgraph');
const { GraphQLError } = require('graphql');
const gql = require('graphql-tag');

const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({ region: 'us-east-1' }));

const typeDefs = gql`
  extend schema @link(url: "https://specs.apollo.dev/federation/v2.0", import: ["@key"])

  type CloudStorageBucket @key(fields: "bucketId") {
    bucketId: ID!
    kmsKeyArn: String
    loggingDestination: String
    corsRules: [String]
  }
`;

const resolvers = {
  CloudStorageBucket: {
    __resolveReference: async (reference, context) => {
      if (!context.auth?.cloudAccountId) {
        throw new GraphQLError('Unauthorized cloud request', { extensions: { code: 'UNAUTHORIZED' } });
      }
      const result = await docClient.send(new GetCommand({
        TableName: 'CloudBuckets',
        Key: { bucketId: reference.bucketId }
      }));
      if (!result.Item || result.Item.cloudAccountId !== context.auth.cloudAccountId) {
        throw new GraphQLError('Access denied to cloud storage bucket', { extensions: { code: 'FORBIDDEN' } });
      }
      return result.Item;
    }
  }
};
